scripts.宋兵死亡.txt:
// 宋兵死亡

	Add($fight029, 1);
	If ($fight029 == 10) @finished;
    Return;
    
@finished:
	StopMusic();
	FadeOut();
	PlayMusic("前途.mp3");
	AddNpc("npc035_蒋伯.ini", 12, 20, 1);
	SetNpcKind("张琳心", 1);
	SetPlayerPos(12, 22);
	SetPlayerDir(4);
	SetPlayerState(0);
	SetNpcPos("张琳心", 11, 21);
	SetNpcDir("张琳心", 5);
	FadeIn();
	Say("蒋伯：小姐，你可回来了，老爷这么好的人，怎么会有罪呢？就是打死我也不信！", 68);
	Say("张琳心：爹爹没罪，是奸人陷害他！爹爹现在何处？", 24);
	Say("蒋伯：老爷从厨房的秘道离开了。小姐还记得吗？就是你小时候和少爷常偷偷溜出去的那条……", 68);
	Say("张琳心：……蒋伯，真难为你了。", 24);		
	Say("张琳心：我这还有点银子，你拿着回乡下养老去吧。", 24);
	Say("蒋伯：老爷对老奴恩重如山，蒋伯怎么能在老爷落难的时候离开呢？老奴就一个人守着这房子，等老爷昭雪后再回来住！", 68);
	Say("张琳心：……", 24);
	Say("蒋伯：小姐，老爷前些天写了一首诗，要我碰见小姐和少爷后就交给你们。", 68);
	Say("张琳心：一首诗？", 21);
	
	SetNpcActionFile("张琳心", 0, "mpc013_3.asf");
	SetNpcActionFile("张琳心", 1, "mpc013_3.asf");
	NpcSpecialAction("蒋伯", "mpc013_1.asf");
	NpcSpecialAction("张琳心", "mpc013_2.asf");
	Sleep(1500);
	
	Say("<color=Red>秋幕雨后屋生苔，", 68);
	Say("<color=Red>残红满地道难开。", 68);
	Say("<color=Red>庭院幽深向阳晚，", 68);
	Say("<color=Red>烟云逐海浪潮来。<color=Black>", 68);
	
	SetNpcActionFile("张琳心", 0, "npc004_st.asf");
	SetNpcActionFile("张琳心", 1, "npc004_pst.asf");
	NpcSpecialAction("张琳心", "mpc013_4.asf");
	
	Say("蒋伯：老爷的意思是……", 68);
	Say("张琳心：爹爹已经先去办一件重要的事情了……", 21);
	Say("蒋伯：小姐你们赶快离开这里，官兵马上又要来了。", 68);
	Say("张琳心：蒋伯，你也要保重！",24);
	SetNpcKind("张琳心", 3);
	SetNpcScript("张琳心", "张琳心对话.txt");
	SetNpcScript("蒋伯", "蒋伯对话.txt");
	Assign($Event, 260);
	SetMapTrap(1, "Trap01.txt");
	SetMapTrap(2, "Trap02.txt");
	Memo("两人再次来到张府，遇到大量宋兵，消灭所有的敌人后，老管家蒋伯告诉两人张风进了后面厨房的秘道。");
	Return;

scripts.护卫死亡.txt:
//护卫死亡

	Add($fight029huwei, 1);
	If ($fight029huwei == 7) @finished;
    Return;
    
@finished:

	Say("护卫：啊——");
	FadeOut();
	StopMusic();
	PlayMusic("前途.mp3");
	SetPlayerPos(7,15);
	SetPlayerDir(4);
	SetPlayerState(0);
	AddNpc("npc008_杨瑛.ini",13,28,7);
	AddNpc("npc021_王佐.ini",13,29,3);
	AddNpc("npc025_杨湖.ini",13,30,4);
	FadeIn();
	
	Say("独孤剑：糟糕！秦老贼不见了！", 9);
	Sleep(500);
	PlayerGoto(10,23);
	SetPlayerDir(7);
	MoveScreen(7, 50, 1);
	Say("王佐：帮主，秦老贼跑掉了。",63);
	Say("杨湖：不知风波亭的兄弟进行得怎样？",100);
	SetNpcDir("杨瑛",3);
	SetNpcDir("杨湖",3);
	SetNpcDir("王佐",3);
	SetPlayerScn();
	Say("杨瑛：独……独孤大哥！",42);
	NpcGoto("杨瑛",11,25);
	NpcGotoEx("杨湖",12,28);
	NpcGoto("王佐",12，27);
	Sleep(800);
	SetNpcDir("杨瑛",3);
	SetNpcDir("杨湖",3);
	SetNpcDir("王佐",3);
	
	Say("杨湖：原来这些朝廷的鹰爪都是独孤兄弟你收拾的啊！",100);
	Say("独孤剑：只可惜，秦老贼跑掉了！",5);
	Say("王佐：岳元帅已被解往风波亭，其他将军被关在大牢之中……",63);
	Say("独孤剑：我赶去风波亭，你们救其他将军！",5);
	PlayerGoto(9, 31);
	SetPlayerDir(1);
	SetNpcDir("杨瑛",1);
	SetNpcDir("杨湖",1);
	SetNpcDir("王佐",1);
	
	Say("杨瑛：你，一向可好！",41);
	Sleep(700);
	Say("独孤剑：我很好……多谢杨姑娘挂念！",1);
	Sleep(500);
	Say("独孤剑：你们小心！",1);
	PlayerGoto(8, 28);
	PlayerGotoEx(4, 35);
	Sleep(500);
	FadeOut();
	
	LoadMap("map120_风波亭.map");
	LoadNpc("map120-1.npc");
	LoadObj("map120-1.obj");
	SetPlayerPos(14,64);
	SetPlayerDir(3);
	FadeIn();
	StopMusic();
	PlayMusic("追缘.mp3");
	Say("独孤剑：让开！",5);
	Say("宋将：岳飞果然勾结这些江湖草寇！这一次，要一网打尽！");
	Say("独孤剑：再不让开，休怪剑下无情！",5);
	SetNpcRelation("宋兵",1);
	Return;

scripts.蒋伯对话.txt:
// 蒋伯对话

	If ($Talkjiangbo == 1) @Talk1;
	If ($Talkjiangbo == 2) @Talk2;
	If ($Talkjiangbo == 3) @Talk3;
	
	Say("蒋伯：小姐，你……放心走吧！", 68);
	Say("蒋伯：老爷的花，蒋伯会好好照料的。",68);
	Assign($Talkjiangbo,1);
	Return;
	
@Talk1:
	Say("蒋伯：少爷千万不要现在回来啊！", 68);
	Assign($Talkjiangbo,2);
	Return;
	
@Talk2:
	Say("蒋伯：老天有眼，老爷的冤情一定会昭雪的。", 68);
	Say("蒋伯：小姐，蒋伯等着小姐、老爷和少爷一起回来的那一天。",68);
	Say("张琳心：蒋伯……",26);
	Say("蒋伯：小姐……你们赶紧走吧！赶紧走！",68);
	Return;
	
@Talk3:
	Say("蒋伯：呜呜……小姐，你要保重！",68);
	Return;

scripts.张琳心对话.txt:
// 张琳心同伴对话

	If ($Talkmap029 == 1) @Talk1;
	If ($Talkmap029 == 2) @Talk2;	
	If ($Talkmap029 == 3) @Talk3;
	If ($Talkmap029 == 4) @Talk4;		
		
	Say("张琳心：他们把娘的遗物都拿走了。", 26);
	Say("独孤剑：……",1);
	Assign($Talkmap029,1);
	Return;
	
@Talk1:
	Say("张琳心：院子里的花，爹爹每天都细心的照料……从今以后……",24);
	Assign($Talkmap029,2);
	
@Talk2:
	Say("张琳心：不知道爹爹现在……是否安然无恙？",24);
	Assign($Talkmap029,3);
	Return;
	
@Talk3:
	Say("张琳心：我现在该怎么办……",26);
	Say("独孤剑：张姑娘，这里已经太危险了，我们还是赶快离开临安去找你爹为好。",1);
	Say("张琳心：独孤大哥，你不找我爹报仇……",26);
	Say("独孤剑：……我先送你离开这里……",1);
	Assign($Talkmap029,4);
	Return;
	
@Talk4:
	Say("张琳心：秘道就在柴房里。",21);
	Return;

scripts.贾老实对话.txt:
// 与贾老实的同伴对话

	If($Event == 120) @Event120;
	Return;
	
@Event120:
	If($Talkmap029jia == 0) @Talk0;
	If($Talkmap029jia == 1) @Talk1;
	If($Talkmap029jia == 2) @Talk2;
	Return;
	
@Talk0:
	Say("贾老实：京城是个花花世界，如果不是因为金兵南下，这里以前更热闹。", 207);
	Assign($Talkmap029jia, 1);
	Return;	
@Talk1:
	Say("贾老实：人生在世，不就是图个吃喝玩乐，老弟，你说呢？", 207);
	Say("独孤剑：如果只顾自己享乐，而置国家安危于不顾，有朝一日金兵南侵，攻破城池，覆巢之下，安有完卵？", 1);
	Say("贾老实：哪里管得了那许多！", 207);
	Say("独孤剑：人人都像你这样想，大宋迟早要亡国。", 1);
	Assign($Talkmap029jia, 2);
	Return;
@Talk2:
	Say("贾老实：我最关心的就是赚钱，别的我可不想管。", 207);
	Say("独孤剑：……", 1);
	Return;

traps.Trap01.txt:
